/* ===================== BÀI 18 · SFR, bit và header thiết bị ===================== */
/* Bài 18 · SFR, bit và header thiết bị (AMTS-EMB-001-M05-L02, MC51-018) — sinh bởi tools/author/mcu8051/l18.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8051 và bài tập chấm tự động (đề, code mẫu, bộ thử). Lời giải không nằm ở đây. */
const P18=[{"label":"Ví dụ: sbit bật, tắt, đảo từng LED","code":"; Ví dụ 1: sbit LED0 = P1^0; sbit LED7 = P1^7;\n; Mã SDCC 4.2.0 sinh cho 01.c51: mỗi dòng C là\n; một lệnh bit 2 byte, 1 chu kỳ máy.\n        ORG     0000H\n        CLR     P1.0                    ; LED0 = 0;     C2 90\n        CLR     P1.7                    ; LED7 = 0;     C2 97\n        CPL     P1.7                    ; LED7 = !LED7; B2 97\n        SJMP    $                       ; while (1);\n        END\n","note":"Mỗi dòng C là một lệnh bit 2 byte, 1 chu kỳ. Đoán trước: sau CPL P1.7, LED nào còn sáng? (Chỉ P1.0: P1 = FEH.) Không lệnh nào chạm 6 chân còn lại.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Đọc nút K1 qua sbit","code":"; Ví dụ 2: sbit K1 = P3^2; sbit LED0 = P1^0;\n; n ở 30H. Mã SDCC 4.2.0 sinh cho 02.c51.\n; Giữ nút K1 rồi bấm Chạy lại để thấy nhánh khác.\n        ORG     0000H\n        MOV     C,P3.2                  ; LED0 = K1;  (qua cờ C)\n        MOV     P1.0,C\n        JB      P3.2,XONG               ; if (!K1)\n        MOV     A,30H                   ;     n++;\n        INC     A\n        MOV     30H,A\nXONG:   SJMP    $                       ; while (1);\n        END\n","note":"LED0 = K1 đi qua cờ C (MOV C,P3.2 rồi MOV P1.0,C). Không nhấn: C = 1, LED tắt, JB nhảy qua n++ (5 chu kỳ). Giữ nút K1 rồi Chạy lại: LED P1.0 sáng và ô 30H thành 01H.","dev":{"led":true,"btn":true},"fosc":12000000},{"label":"Ví dụ: Biến bit trong vùng 20H–2FH","code":"; Ví dụ 3: bit ready; x ở 30H. Trình liên kết SDCC\n; đặt ready ở địa chỉ bit 00H = bit 0 của ô 20H.\n        ORG     0000H\n        MOV     30H,#84H                ; x = 0x84;\n        CLR     00H                     ; ready = 0;\n        MOV     A,30H                   ; if (x & 0x80)\n        JNB     ACC.7,KIEM              ;   (thử bit 7 của A)\n        SETB    00H                     ;     ready = 1;\nKIEM:   JNB     00H,XONG                ; if (ready)\n        MOV     P1,#0F0H                ;     P1 = 0xF0;\nXONG:   SJMP    $                       ; while (1);\n        END\n","note":"Biến bit ready nằm ở bit 00H = bit 0 của ô 20H (xem ô 20H trong Bộ nhớ đổi từ 00H thành 01H sau SETB 00H). JNB ACC.7 thử bit 7 của x = 84H mà không cần AND cả byte.","dev":{"led":true},"fosc":12000000},{"label":"Ví dụ: Byte bdata và sbit trên từng bit","code":"; Ví dụ 4: flags ở 20H (bdata); FL0 = bit 00H,\n; FL7 = bit 07H. Mã SDCC 4.2.0 sinh cho 04.c51.\n        ORG     0000H\n        MOV     20H,#81H                ; flags = 0x81; (cả byte)\n        CLR     00H                     ; FL0 = 0;  (chỉ bit 0)\n        JNB     07H,XONG                ; if (FL7)\n        MOV     P1,20H                  ;     P1 = flags;\nXONG:   SJMP    $                       ; while (1);\n        END\n","note":"Cùng ô 20H, hai cách nhìn: MOV 20H,#81H ghi cả byte, CLR 00H chỉ xóa bit 0. Đoán trước: sau CLR 00H, ô 20H bằng bao nhiêu? (80H.) Bit 07H vẫn = 1 nên P1 = flags = 80H: chỉ LED P1.7 tắt.","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: ~ trên bit luôn cho 1 (SDCC)","code":"; Ví dụ 5 (bẫy): LED0 = ~LED0; với sbit LED0 = P1^0\n; ~ nâng bit lên int: ~0 = FFFFH, ~1 = FFFEH, đều\n; khác 0, nên SDCC gán vào bit luôn cho 1 (SETB).\n        ORG     0000H\n        CLR     P1.0                    ; LED0 = 0;\n        SETB    P1.0                    ; LED0 = ~LED0;  (không đảo)\n        SETB    P1.0                    ; LED0 = ~LED0;  (vẫn là 1)\n        SJMP    $                       ; while (1);\n        END\n","note":"Bẫy: ~ nâng bit lên int, ~0 = FFFFH ≠ 0 nên phép gán cho 1. SDCC sinh SETB thay vì CPL và cảnh báo warning 180 (Keil C51 có thể sinh CPL: chưa kiểm). Đoán trước: sau hai lần “đảo”, LED P1.0 sáng hay tắt? (Tắt: P1 = FFH.) Sửa: LED0 = !LED0;","dev":{"led":true},"fosc":12000000},{"label":"Bẫy: if (K1 = 0) ghi 0 vào chốt nút","code":"; Ví dụ 6 (bẫy): if (K1 = 0) thay cho if (K1 == 0)\n; Phép gán ghi 0 vào chốt P3.2: chân bị kéo xuống,\n; từ đó đọc K1 luôn được 0 dù không ai nhấn nút.\n        ORG     0000H\n        CLR     P3.2                    ; K1 = 0  (phép gán!)\n        JNB     P3.2,TIEP               ; if (K1): đọc lại chân = 0\n        CLR     P1.0                    ;     LED0 = 0; (bị bỏ qua)\nTIEP:   MOV     C,P3.2                  ; LED0 = K1;  (C = 0)\n        MOV     P1.0,C                  ;   LED P1.0 sáng\n        SJMP    $                       ; while (1);\n        END\n","note":"Bẫy: K1 = 0 là phép gán. CLR P3.2 ghi 0 vào chốt nút, nên đọc lại chân luôn được 0 dù không nhấn: LED P1.0 sáng, P3 = FBH. Thử giữ hay thả K1: kết quả không đổi. Sửa: if (K1 == 0).","dev":{"led":true,"btn":true},"fosc":12000000}];
const sim18=makeSim51(document.getElementById("m51-l18"),{id:"s18",presets:P18,ram:256});
makeEx51(document.getElementById("ex-l18"),"l18",[{"t":"Đèn báo theo cờ lệnh","d":"<p>Viết đoạn hợp ngữ làm đúng việc của đoạn C51 sau. Biến <code>unsigned char bdata cmd _at_ 0x20;<\/code>, <code>sbit RUN = cmd^0;<\/code>, <code>sbit DIR = cmd^1;<\/code>; LED tích cực mức thấp: <code>sbit LRUN = P1^0;<\/code>, <code>sbit LDIR = P1^1;<\/code>, <code>sbit LALL = P1^7;<\/code>.<\/p><pre class=\"mc-asm\">LRUN = !RUN;\nLDIR = !DIR;\nLALL = !(RUN &amp; DIR);<\/pre><p>Các bit khác của P1 giữ 1, ô <code>20H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>20H = 01H<\/code> → <code>P1 = FEH<\/code>.<\/p>","start":"; Bài tập 1: cmd ở 20H. RUN = cmd^0, DIR = cmd^1.\n; LED P1.0, P1.1, P1.7 sáng khi chân = 0.\n        ORG     0000H\n        MOV     C,00H                   ; C = RUN (bit 00H = 20H.0)\n        MOV     P1.0,C                  ; LRUN = RUN;  chưa đảo!\n; Viết tiếp: LDIR = !DIR;  LALL = !(RUN & DIR);\n        SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x20":1}},"expect":{"iram":{"0x20":1},"ports":{"P1":254}}},{"setup":{"iram":{"0x20":0}},"expect":{"iram":{"0x20":0},"ports":{"P1":255}}},{"setup":{"iram":{"0x20":2}},"expect":{"iram":{"0x20":2},"ports":{"P1":253}}},{"setup":{"iram":{"0x20":3}},"expect":{"iram":{"0x20":3},"ports":{"P1":124}}},{"setup":{"iram":{"0x20":252}},"expect":{"iram":{"0x20":252},"ports":{"P1":255}}},{"setup":{"iram":{"0x20":255}},"expect":{"iram":{"0x20":255},"ports":{"P1":124}}}]},"hints":["RUN là bit 0 của ô 20H, tức địa chỉ bit 00H; DIR là địa chỉ bit 01H. Đọc bit vào cờ C bằng MOV C,00H.","! trên một bit là đảo bit: CPL C. Ghi C ra chân bằng MOV P1.0,C (lệnh bit, chỉ đổi đúng chân đó).","Bộ xử lý bit có lệnh AND trên cờ C với một địa chỉ bit: tính phép AND ngay trong C, rồi đảo và ghi ra chân như câu trước."],"why":"Lệnh bit chỉ đổi một chân nên các LED khác giữ nguyên. Bộ thử 5 (cmd = FCH) bắt lỗi xét cả byte cmd thay vì từng bit; bộ thử 4 bắt lỗi dùng ORL C thay vì ANL C."},{"t":"Đèn theo công tắc","d":"<p>Viết đoạn hợp ngữ làm đúng việc của đoạn C51 sau. <code>unsigned char bdata sw _at_ 0x22;<\/code> (8 công tắc đã đọc sẵn), <code>unsigned char data n _at_ 0x30;<\/code>, <code>sbit EN = sw^7;<\/code>.<\/p><pre class=\"mc-asm\">if (EN) {\n    P1 = ~(sw &amp; 0x0F);\n    n++;\n} else {\n    P1 = 0xFF;\n}<\/pre><p>Ô <code>22H<\/code> giữ nguyên. Kết thúc bằng <code>SJMP $<\/code>.<\/p><p>Ví dụ: <code>22H = 85H<\/code>, <code>30H = 10H<\/code> → <code>P1 = FAH<\/code>, <code>30H = 11H<\/code>.<\/p>","start":"; Bài tập 2: sw ở 22H (bdata), n ở 30H, EN = sw^7.\n        ORG     0000H\n        JNB     07H,TAT                 ; if (EN)  kiểm lại địa chỉ bit!\n; Viết ở đây: P1 = ~(sw & 0x0F);  n++;\n        SJMP    XONG\nTAT:    MOV     P1,#0FFH                ; else P1 = 0xFF;\nXONG:   SJMP    $\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x20":0,"0x22":133,"0x30":16}},"expect":{"iram":{"0x22":133,"0x30":17},"ports":{"P1":250}}},{"setup":{"iram":{"0x20":0,"0x22":5,"0x30":16}},"expect":{"iram":{"0x22":5,"0x30":16},"ports":{"P1":255}}},{"setup":{"iram":{"0x20":0,"0x22":128,"0x30":0}},"expect":{"iram":{"0x22":128,"0x30":1},"ports":{"P1":255}}},{"setup":{"iram":{"0x20":0,"0x22":143,"0x30":1}},"expect":{"iram":{"0x22":143,"0x30":2},"ports":{"P1":240}}},{"setup":{"iram":{"0x20":128,"0x22":127,"0x30":16}},"expect":{"iram":{"0x22":127,"0x30":16},"ports":{"P1":255}}},{"setup":{"iram":{"0x20":0,"0x22":250,"0x30":255}},"expect":{"iram":{"0x22":250,"0x30":0},"ports":{"P1":245}}}]},"hints":["Địa chỉ bit của sbit trên biến bdata = (địa chỉ byte − 20H) × 8 + số bit. Code mẫu dùng 07H: đó là bit 7 của ô 20H, không phải của sw.","EN là bit 7 của ô 22H: tính địa chỉ bit theo công thức trên rồi thay vào lệnh JNB của code mẫu.","Trong nhánh EN = 1, mỗi phép trong C (che 4 bit, ~, gán P1, n++) là một lệnh 8051."],"why":"Bộ thử 5 đặt bit 7 của ô 20H = 1 nhưng EN = 0: dùng nhầm địa chỉ bit 07H sẽ bật đèn sai. Bộ thử 3 kiểm n vẫn tăng khi 4 bit thấp = 0; bộ thử 6 kiểm n = FFH quay về 00H và các bit 4–6 của sw bị che."},{"t":"Đảo bit nhanh nhờ vùng bit","d":"<p>Đoạn C51 dưới đây đảo thứ tự 8 bit của <code>x<\/code> (ô <code>30H<\/code>) và ghi vào <code>y<\/code> (ô <code>31H<\/code>): bit 0 của x thành bit 7 của y…<\/p><pre class=\"mc-asm\">v = x;  r = 0;\nfor (i = 0; i &lt; 8; i++) {\n    r = (r &lt;&lt; 1) | (v &amp; 1);\n    v &gt;&gt;= 1;\n}\ny = r;<\/pre><p>Code mẫu là mã SDCC 4.2.0 sinh cho đoạn này: đúng, 26 byte, nhưng 128 chu kỳ máy. Hãy viết lại để với mọi <code>x<\/code>: (1) <code>31H<\/code> đúng; (2) <code>30H<\/code> giữ nguyên; (3) chạy không quá <b>32 chu kỳ máy<\/b> (tính cả một lần <code>SJMP $<\/code>); (4) mã không quá <b>40 byte<\/b>. Được dùng ô <code>20H<\/code>, <code>21H<\/code> làm vùng nháp.<\/p>","start":"; Bài tập 3: y (31H) = x (30H) đảo thứ tự bit.\n; Đây là mã SDCC 4.2.0 sinh cho đề: đúng nhưng chậm.\n; Sửa để chạy <= 32 chu kỳ máy và <= 40 byte.\n; Được dùng ô 20H, 21H làm vùng nháp.\n        ORG     0000H\n        MOV     R7,30H                  ; v = x;\n        MOV     R6,#00H                 ; r = 0;\n        MOV     R5,#08H                 ; for (i = 0; i < 8; i++)\nVONG:   MOV     04H,R6                  ; r = (r << 1) | (v & 1);\n        MOV     A,R4\n        ADD     A,R4\n        MOV     R4,A\n        MOV     A,#01H\n        ANL     A,R7\n        ORL     A,R4\n        MOV     R6,A\n        MOV     A,R7                    ; v >>= 1;\n        CLR     C\n        RRC     A\n        MOV     R7,A\n        DJNZ    R5,VONG\n        MOV     31H,R6                  ; y = r;\n        SJMP    $                       ; while (1);\n        END\n","spec":{"cases":[{"setup":{"iram":{"0x20":90,"0x21":195,"0x30":1,"0x31":238}},"expect":{"iram":{"0x30":1,"0x31":128}}},{"setup":{"iram":{"0x20":90,"0x21":195,"0x30":0,"0x31":238}},"expect":{"iram":{"0x30":0,"0x31":0}}},{"setup":{"iram":{"0x20":90,"0x21":195,"0x30":255,"0x31":238}},"expect":{"iram":{"0x30":255,"0x31":255}}},{"setup":{"iram":{"0x20":90,"0x21":195,"0x30":165,"0x31":238}},"expect":{"iram":{"0x30":165,"0x31":165}}},{"setup":{"iram":{"0x20":90,"0x21":195,"0x30":18,"0x31":238}},"expect":{"iram":{"0x30":18,"0x31":72}}},{"setup":{"iram":{"0x20":90,"0x21":195,"0x30":240,"0x31":238}},"expect":{"iram":{"0x30":240,"0x31":15}}}],"maxCyc":32,"maxBytes":40},"hints":["Vòng lặp tốn 15 chu kỳ mỗi bit. Không vòng lặp nào xuống dưới 32 chu kỳ được: phải viết thẳng 8 lần (trải vòng lặp).","Chép x vào ô 20H (MOV 20H,30H): từ đó bit k của x là địa chỉ bit 0k H, đọc từng bit bằng MOV C,0kH (1 chu kỳ).","Khi x đã nằm trong vùng bit, mỗi bit là một cặp lệnh: đọc bit vào C, ghi C vào bit đích của A. Tính lại tổng chu kỳ."],"why":"SDCC giữ v, r trong R7, R6 và dịch từng bit bằng ADD, ANL, ORL, RRC: 15 chu kỳ mỗi vòng. Vùng bit 20H–2FH cho phép đọc/ghi từng bit trực tiếp bằng MOV C,bit và MOV bit,C, nên trải 8 lần chỉ còn 3 chu kỳ mỗi bit. Cách khác: tra bảng 16 phần tử cho từng nửa byte (MOVC, Bài 19) cũng đạt."}]);

makeQuiz("quiz18","score18",[{"q": "Với sbit LED7 = P1^7; (Keil C51), địa chỉ bit của LED7 là gì?", "o": ["87H", "17H", "90H XOR 07H = 97H, vì ^ là phép XOR", "97H"], "a": 3, "e": "P1 ở 90H chia hết cho 8 nên bit k có địa chỉ 90H + k: LED7 = 97H. Trong dòng sbit, ^ nghĩa là “bit số”, không phải XOR (dù kết quả số trùng nhau ở trường hợp này)."}, {"q": "unsigned char bdata sw _at_ 0x22; sbit EN = sw^7; EN có địa chỉ bit nào?", "o": ["07H", "29H", "17H", "A7H"], "a": 2, "e": "Bit k của ô a trong vùng 20H–2FH có địa chỉ (a − 20H) × 8 + k = 2 × 8 + 7 = 23 = 17H. 07H là bit 7 của ô 20H."}, {"q": "Dịch bằng SDCC 4.2.0: sbit LED0 = P1^0; Sau LED0 = 0; LED0 = ~LED0; thì LED0 bằng bao nhiêu?", "o": ["0, vì ~ không đổi bit 0", "1, và lần ~LED0 tiếp theo sẽ cho 0", "Không xác định, trình biên dịch báo lỗi", "1, vì ~0 là int FFFFH khác 0"], "a": 3, "e": "Bit được nâng lên int trước khi đảo: ~0 = FFFFH, ~1 = FFFEH, cả hai khác 0, nên SDCC gán vào bit luôn cho 1 (sinh SETB, warning 180). Keil C51 có thể xử lý khác (chưa kiểm). Dùng ! để đảo một bit: đúng trên mọi trình biên dịch."}, {"q": "Vì sao SDCC báo lỗi cho bit list[4]; ?", "o": ["8051 không có mảng bit và không có con trỏ tới bit", "Vùng bit chỉ có 4 bit trống", "Phải viết __bit thay cho bit", "Mảng phải khai báo trong hàm main"], "a": 0, "e": "Lệnh bit chỉ nhận địa chỉ bit cố định trong lệnh, không có cách định địa chỉ bit gián tiếp, nên C51/SDCC không cho mảng hay con trỏ tới bit (SDCC: error 50)."}, {"q": "Đoạn if (K1 = 0) LED0 = 0; với sbit K1 = P3^2 (nút nhấn) gây hậu quả gì?", "o": ["Không sao, vì K1 là chân vào nên không ghi được", "Ghi 0 vào chốt P3.2: từ đó đọc K1 luôn được 0", "Trình biên dịch báo lỗi gán vào sbit", "LED0 luôn sáng nhưng nút vẫn đọc đúng"], "a": 1, "e": "Phép gán sinh CLR P3.2. Chân 8051 chỉ đọc được mức ngoài khi chốt = 1; chốt = 0 kéo chân xuống, nên nút mất tác dụng. SDCC không cảnh báo."}]);

